-- 更新公告升到 v1.1（2026-10-13）：AI 助手全面上线
-- 覆盖上一版 v1.0 的内容（UPDATE 而非 INSERT），version 变为 v1.1
-- 前端 ChangelogModal 检测到版本号变化，即向所有用户弹出本公告。
UPDATE site_settings
SET value = '{"version":"v1.1","title":"v1.1 更新公告：AI 助手全面上线","updated_at":"2026-10-13","items":["新增岗位时可一键让 AI 起草岗位职责、任职要求、学历与经验要求、薪资建议，只需补岗位名称即可","招聘概览新增「AI 复盘」：按漏斗、周期、渠道、淘汰原因自动写出一段复盘结论，可一键复制","招聘看板新增「AI 下一步建议」：结合候选人阶段与停留时长，给出该做什么、怎么跟进的话术草稿","待办日历新增「AI 今日重点」：按逾期与到期时间排出今天先做什么","审批中心新增「10 秒读卡」：打开审批即可看到该审批的来龙去脉摘要","入职办理可由 AI 生成材料清单初稿；人才库支持一键盘点待跟进","AI 生成结果会保留，下次进入该页面直接看到历史产出，不用重复生成","AI 额度可在「系统设置 → AI 配额」里调整；管理员账号不限次数","招聘概览改版：关键指标合并为通栏卡片，逾期待办带红色角标可直接点进清理","转化漏斗支持 5 套配色切换，高度自适应不再过长；招聘周期与渠道转化率新增图形化展示","审批中心列表改为撑满整屏高度，表头固定、内容区滚动","模板库、人才库、简历预览、招聘需求与智能匹配页均有功能增强"]}'
WHERE key = 'app_changelog';